    expect(strictRules).toEqual(configs.recommended[0].rules);
  });,Flat-config integration tests with ESLint v9 (tests/config/flat-config-presets-integration.test.ts):
- Uses FlatESLint from "eslint/use-at-your-own-risk" to exercise ESLint v9 flat config integration:
  import { FlatESLint } from "eslint/use-at-your-own-risk";
  import { configs, default as traceabilityPlugin } from "../../src/index";

  const baseConfig = {
    plugins: { traceability: traceabilityPlugin },
    rules: {},
  };

  async function lintTextWithConfig(text: string, config: any) {
    const eslint = new FlatESLint({
      overrideConfig: config,
      overrideConfigFile: true,
      ignore: false,
    } as any);
    const [result] = await eslint.lintText(text, { filePath: "example.js" });
    return result;
  }

- Confirms presets enable the plugin rules via flat config:
  it("[REQ-CONFIG-PRESETS] recommended preset enables traceability rules via documented usage", async () => {
    const config = [baseConfig, ...configs.recommended];
    const code = "function foo() {}";
    const result = await lintTextWithConfig(code, config);
    const ruleIds = result.messages.map((m) => m.ruleId).sort();
    expect(ruleIds).toContain("traceability/require-story-annotation");
  });,CLI integration tests exercising plugin registration and loading via ESLint CLI (tests/integration/cli-integration.test.ts):
