- Uses ESLint CLI with the repository's flat config (eslint.config.js):
  const eslintPkgDir = path.dirname(require.resolve("eslint/package.json"));
  const eslintCliPath = path.join(eslintPkgDir, "bin", "eslint.js");
  const configPath = path.resolve(__dirname, "../../eslint.config.js");

  function runEslint(code: string, rule: string) {
    const args = [
      "--no-config-lookup",
      "--config",
      configPath,
      "--stdin",
      "--stdin-filename",
      "foo.js",
      "--rule",
      "no-unused-vars:off",
      "--rule",
      rule,
    ];
    const result = spawnSync(process.execPath, [eslintCliPath, ...args], { encoding: "utf-8", input: code });
    return result;
  }

- Parameterized tests verify correct exit status for various rules and code samples:
  it.each(tests)("[REQ-PLUGIN-STRUCTURE] $name", ({ code, rule, expectedStatus }) => {
    const result = runEslint(code, rule);
    expect(result.status).toBe(expectedStatus);
  });

