  // eslint.config.js
  import js from "@eslint/js";
  import traceability from "eslint-plugin-traceability";

  export default [
    js.configs.recommended,
    {
      plugins: {
        traceability,
      },
    },
    ...traceability.configs.recommended,
  ];
